// Selected review request for the Approvals page (details card + history modal).
// Runs on requests.onDataQuerySuccess, the page's onPageLoad and reviewQueue.onRowClicked.
const s = v => String(v ?? '');
const rows = queries.requests.data || [];
const inReview = r => ['Manager review', 'Security review'].includes(r.status);
const selId = components.reviewQueue?.selectedRow?.id;
const r = rows.find(x => x.id === selId && inReview(x)) || rows.find(inReview);
if (!r) return { has: false, code: 'No requests awaiting review.', name: '', dept: '', app: '', role: '', until: '', cls: '', justification: '', decisions: '', history: [] };
return {
  has: true,
  code: s(r.request_code) + ' · ' + s(r.status),
  name: s(r.employee_name),
  dept: s(r.department) + ' · Manager: ' + s(r.manager),
  app: s(r.application_name),
  role: s(r.role),
  until: 'Until ' + s(r.expires_on),
  cls: s(r.classification) + ' data',
  justification: s(r.justification),
  decisions: 'Manager: ' + s(r.manager_decision) + ' · Security: ' + s(r.security_decision),
  history: (r.history || []).slice().reverse().map(h => ({ meta: s(h.at) + ' · ' + s(h.actor), action: s(h.action), note: s(h.note) }))
};
